<script lang="ts">
 import {languageOverrides} from "./localization";import {invoke} from '@tauri-apps/api/core';import {native} from './storage';import {printRequest} from './print-dialog';import {translator} from './i18n';import {Printer,X} from '@lucide/svelte';export let language:'ru'|'ro'|'en';let printers:string[]=[],printer='',landscape=false,color=true,copies=1,pages='',error='',busy=false,loaded:unknown=null;$:t=translator(language,$languageOverrides);$:if($printRequest&&loaded!==$printRequest){loaded=$printRequest;landscape=$printRequest.landscape;if(native)invoke<{printers:string[];default:string|null;native:boolean}>('available_printers').then(result=>{printers=result.printers;printer=result.default||printers[0]||'';if(!result.native)fallback();}).catch(e=>error=String(e));else fallback();}
 function finish(result:boolean){const request=$printRequest;printRequest.set(null);request?.resolve(result);error='';}
 function fallback(){const request=$printRequest;if(!request)return;const frame=document.createElement('iframe');frame.style.cssText='position:fixed;left:-10000px;width:1100px;height:900px';frame.srcdoc=request.html;frame.onload=()=>{frame.contentWindow?.focus();frame.contentWindow?.print();setTimeout(()=>frame.remove(),1000);};document.body.append(frame);finish(true);}
 async function print(){if(!$printRequest)return;try{busy=true;const html=$printRequest.render?$printRequest.render(landscape):$printRequest.html.replace(/size:\s*A4(?:\s+(?:portrait|landscape))?/g,'size:A4 '+(landscape?'landscape':'portrait'));await invoke('print_document',{html,printer,landscape,color,copies,pages});window.dispatchEvent(new CustomEvent('openhau:notify',{detail:{text:t('Документ отправлен на печать.','Documentul a fost trimis la imprimare.','Document sent to the printer.')}}));finish(true);}catch(e){error=String(e);}finally{busy=false;}}
</script>
{#if $printRequest}<div class="print-backdrop"><form onsubmit={e=>{e.preventDefault();void print();}}><header><Printer size={22}/><h2>{t('Печать','Imprimare')}</h2></header><label>{t('Принтер','Imprimantă','Printer')}<select bind:value={printer}>{#each printers as name}<option value={name}>{name}</option>{/each}</select></label><label>{t('Копий','Copii','Copies')}<input type="number" min="1" max="999" bind:value={copies}/></label><label>{t('Страницы','Pagini','Pages')}<input placeholder={t('Все страницы','Toate paginile','All pages')} bind:value={pages}/></label><label>{t('Ориентация','Orientare','Orientation')}<select bind:value={landscape}><option value={false}>{t('Книжная','Portret','Portrait')}</option><option value={true}>{t('Альбомная','Peisaj','Landscape')}</option></select></label><label class="check-row"><input type="checkbox" bind:checked={color}/>{t('Цветная печать','Imprimare color','Print in color')}</label><p>{t('Колонтитулы браузера отключены. Цвет доступен, если его поддерживает выбранный принтер.','Antetele și subsolurile browserului sunt dezactivate. Culoarea depinde de imprimanta selectată.','Browser headers and footers are disabled. Color output requires a color printer.')}</p>{#if error}<p class="alert error" role="alert">{error}</p>{/if}<footer><button type="button" class="button secondary" disabled={busy} onclick={()=>finish(false)}>{t('Отмена','Anulează')}</button><button type="submit" class="button" disabled={!printer||busy}><Printer size={17}/>{t('Печать','Imprimare')}</button></footer></form></div>{/if}
<style>.print-backdrop{position:fixed;inset:0;z-index:90000;display:grid;place-items:center;background:#0006;backdrop-filter:blur(8px)}form{width:min(470px,calc(100vw - 40px));display:grid;gap:18px;padding:24px;box-sizing:border-box;background:var(--surface);color:var(--text)}header,footer{display:flex;gap:12px;align-items:center}h2{margin:0;font-size:22px}label:not(.check-row){display:grid;gap:7px}p{font-size:12px;color:var(--muted);line-height:1.6}footer{justify-content:flex-end}</style>
